import 'package:flutter/foundation.dart'; import '../models/order.dart'; import '../models/cart_item.dart';
class OrderProvider extends ChangeNotifier {final List<CustomerOrder> orders=[]; CustomerOrder create(List<CartItem> items,String address,double subtotal,double delivery){final o=CustomerOrder(id:'ZP${DateTime.now().millisecondsSinceEpoch.toString().substring(5)}',createdAt:DateTime.now(),items:items.map((x)=>CartItem(product:x.product,quantity:x.quantity)).toList(),subtotal:subtotal,deliveryFee:delivery,discount:0,total:subtotal+delivery,address:address,paymentMethod:'COD');orders.insert(0,o);notifyListeners();return o;}}
